using namespace std;
const int N = 1005;
char mat[N][N];
int a[N][N];
const int d[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
int main() {

    int n, m, ans = 0;
    scanf("%d%d", &n, &m);
    assert(1 <= n && n <= 1000);
    assert(1 <= m && m <= 1000);

    for (int i = 1; i <= n; i ++)
        scanf("%s", mat[i] + 1);
    for (int i = 1; i <= n; i ++)
        for (int j = 1; j <= m; j ++) {
            int num = 0, p = -1;
            for (int k = 0; k < 4; k ++)
                if (mat[i + d[k][0]][j + d[k][1]] == '#')
                    num ++, p = k;
            if (mat[i][j] == '.' && num == 1)
                a[i + d[p][0]][j + d[p][1]] ++;
            else if (mat[i][j] == '.' && num == 0)
                ans ++;
            else if (mat[i][j] == '#' && num == 0)
                a[i][j] ++;
        }
    int mx = 0;
    for (int i = 1; i <= n; i ++)
        for (int j = 0; j <= m; j ++)
            mx = max(mx, a[i][j]);
    cout << ans + mx << endl;
    return 0;
}

