#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

// 独立实现：base = 四邻无 # 的 . 数；对每个 # 格，
// 增益 = 恰有 1 个 # 邻（即该格）的相邻 . 数 + (该 # 格四邻无 # ? 1 : 0)；
// 答案 = base + max(0, 所有 # 格增益)。
static long long expected(const vector<string>& g) {
    const int n = (int)g.size(), m = (int)g[0].size();
    const int di[4] = {-1, 1, 0, 0}, dj[4] = {0, 0, -1, 1};
    vector<vector<long long> > cnt(n, vector<long long>(m, 0));
    long long base = 0;
    for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) {
        int h = 0, hp = -1;
        for (int k = 0; k < 4; k++) {
            int ni = i + di[k], nj = j + dj[k];
            if (ni >= 0 && ni < n && nj >= 0 && nj < m && g[ni][nj] == '#') { h++; hp = k; }
        }
        if (g[i][j] == '.') {
            if (h == 0) base++;
            else if (h == 1) cnt[i + di[hp]][j + dj[hp]]++;
        } else {
            if (h == 0) cnt[i][j]++;
        }
    }
    long long mx = 0;
    for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) mx = max(mx, cnt[i][j]);
    return base + mx;
}
static bool check(const string& exe, const string& in, int id) {
    const string inF = "l4a03p1_in.txt", outF = "l4a03p1_out.txt";
    {
        ofstream o(inF);
        o << in;
    }
    int code = system(("\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null").c_str());
    ifstream fis(outF);
    string got((istreambuf_iterator<char>(fis)), istreambuf_iterator<char>());
    string exp;
    istringstream iss(in);
    int n, m;
    iss >> n >> m;
    vector<string> g(n);
    for (int i = 0; i < n; i++) iss >> g[i];
    exp = to_string(expected(g)) + "\n";
    // 归一化：去行尾空白与末尾多余空白
    auto norm = [](string s) {
        istringstream is(s);
        vector<string> lines; string line;
        while (getline(is, line)) {
            while (!line.empty() && (line.back() == ' ' || line.back() == '\r')) line.pop_back();
            lines.push_back(line);
        }
        while (!lines.empty() && lines.back().empty()) lines.pop_back();
        string r;
        for (size_t i = 0; i < lines.size(); i++) r += lines[i] + "\n";
        return r;
    };
    if (code != 0 || norm(got) != norm(exp)) {
        cout << "[FAIL] case " << id << ": status=" << code
             << ", actual=" << got.substr(0, 120) << ", expected=" << exp << "\n";
        return false;
    }
    return true;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    int passed = 0, total = 0;
    vector<pair<string, string> > fixedCases = {
        {"3 5\n.....\n.#..#\n.....", "样例"},
        {"1 1\n.", "1x1 全荒地"},
        {"1 1\n#", "1x1 全杂物"},
        {"2 2\n##\n##", "2x2 全杂物"},
        {"2 2\n..\n..", "2x2 全荒地"},
        {"2 3\n#.#\n...", "杂例 1"},
        {"3 3\n...\n.#.\n...", "杂例 2"},
        {"3 3\n###\n#.#\n###", "杂例 3（中心无 # 邻）"},
    };
    for (size_t i = 0; i < fixedCases.size(); i++) {
        ++total;
        if (check(exe, fixedCases[i].first, 1 + i)) ++passed;
    }
    srand(20250301);
    for (int t = 0; t < 4; t++) {
        int n = 1 + rand() % 80, m = 1 + rand() % 80;
        string in;
        in += to_string(n) + " " + to_string(m) + "\n";
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) in += (rand() % 3 ? '.' : '#');
            in += "\n";
        }
        ++total;
        if (check(exe, in, 9 + t)) ++passed;
    }
    {
        string in = "1000 1000\n";
        string line;
        for (int j = 0; j < 1000; j++) line += '.';
        for (int i = 0; i < 1000; i++) in += line + "\n";
        ++total;
        if (check(exe, in, 13)) ++passed;
    }
    {
        int n = 500, m = 500;
        string in = to_string(n) + " " + to_string(m) + "\n";
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) in += (rand() % 2 ? '.' : '#');
            in += "\n";
        }
        ++total;
        if (check(exe, in, 14)) ++passed;
    }
    cout << "Results: " << passed << "/" << total << " passed" << "\n";
    return passed == total ? 0 : 1;
}

