static long long expected2(const string& in) {
    istringstream iss(in);
    int n, m;
    iss >> n >> m;
    vector<vector<long long> > a(n + 1, vector<long long>(m + 1));
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            iss >> a[i][j];
    long long ans = 0;
    for (int i = 1; i < n; i++)
        for (int j = 1; j < m; j++)
            if (a[i][j] * a[i + 1][j + 1] == a[i + 1][j] * a[i][j + 1])
                ans++;
    return ans;
}
static bool check(const string& exe, const string& in, int id) {
